-- The contact form and the newsletter (completion roadmap, phase 13, section 18.4). Written whole in step 13.2; the
-- newsletter's table is used from step 13.4.

-- A message of the «تماس با ما» form. ticketCode is the only id that leaves the server (CT- and 6 random digits,
-- decision 4). The phone and the email are personal: the nightly job deletes a CLOSED message a year after its last
-- change (decision 19). repliedBy is the operator's userId; reply, its channel and its time come together.
CREATE TABLE contactmessage_tbl
(
    "pId"          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ticketCode"   VARCHAR(9)    NOT NULL UNIQUE CHECK ("ticketCode" ~ '^CT-[0-9]{6}$'),
    topic          VARCHAR(16)   NOT NULL CHECK (topic IN ('ORDER_FOLLOWUP', 'PRODUCT_QUESTION', 'RETURN', 'COLLABORATION', 'OTHER')),
    "fullName"     VARCHAR(80)   NOT NULL CHECK (char_length(btrim("fullName")) >= 3),
    phone          VARCHAR(11)   NOT NULL CHECK (phone ~ '^09[0-9]{9}$'),
    email          VARCHAR(254) CHECK (email = lower(email)),
    "orderCode"    VARCHAR(16),
    message        VARCHAR(600)  NOT NULL CHECK (char_length(btrim(message)) >= 10),
    status         VARCHAR(12)   NOT NULL CHECK (status IN ('OPEN', 'IN_PROGRESS', 'CLOSED')),
    reply          VARCHAR(1000),
    "replyChannel" VARCHAR(5) CHECK ("replyChannel" IN ('SMS', 'EMAIL')),
    "repliedAt"    TIMESTAMPTZ,
    "repliedBy"    BIGINT,
    "internalNote" VARCHAR(1000),
    "userId"       BIGINT,
    "createdAt"    TIMESTAMPTZ   NOT NULL,
    "updatedAt"    TIMESTAMPTZ   NOT NULL,
    CONSTRAINT contactmessage_reply_check
        CHECK ((reply IS NULL) = ("replyChannel" IS NULL) AND (reply IS NULL) = ("repliedAt" IS NULL) AND (reply IS NULL) = ("repliedBy" IS NULL)),
    CONSTRAINT contactmessage_email_reply_check CHECK ("replyChannel" <> 'EMAIL' OR email IS NOT NULL)
);
-- The panel's queue (status, newest first) and the limit per phone (decision 3).
CREATE INDEX contactmessage_queue_idx ON contactmessage_tbl (status, "createdAt" DESC);
CREATE INDEX contactmessage_phone_idx ON contactmessage_tbl (phone, "createdAt");

-- A newsletter subscriber. The email in lower case, so Sara@Example.com and sara@example.com are one (decision 12);
-- token is the unsubscribe link's (decision 13). A row UNSUBSCRIBED for 90 days is deleted by the nightly job.
CREATE TABLE newslettersubscription_tbl
(
    "pId"            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email            VARCHAR(254) NOT NULL UNIQUE CHECK (email = lower(email)),
    status           VARCHAR(12)  NOT NULL CHECK (status IN ('ACTIVE', 'UNSUBSCRIBED')),
    source           VARCHAR(30) CHECK (source ~ '^[a-z0-9_-]+$'),
    token            VARCHAR(35)  NOT NULL UNIQUE CHECK (token ~ '^nl_[0-9A-Za-z]{32}$'),
    "subscribedAt"   TIMESTAMPTZ  NOT NULL,
    "unsubscribedAt" TIMESTAMPTZ,
    CONSTRAINT newsletter_unsubscribed_check CHECK ((status = 'UNSUBSCRIBED') = ("unsubscribedAt" IS NOT NULL))
);
CREATE INDEX newsletter_list_idx ON newslettersubscription_tbl (status, "subscribedAt" DESC);
